// One item per source. Keep this list in the node, in a database or in an
// env var — it does not matter. What matters is that every source carries an
// id, because the heartbeat is keyed on it. A source without an id cannot be
// reported as silent, and a source that cannot be reported as silent is the
// exact failure this workflow exists to prevent.

const sources = [
  {
    id: 'hn-jobs',
    label: 'Hacker News — who is hiring',
    url: 'https://hacker-news.firebaseio.com/v0/topstories.json',
    // How long this source may stay quiet before it counts as broken.
    // Set it from how often the source actually changes, not from hope.
    silentAfterHours: 6,
  },
  {
    id: 'example-feed',
    label: 'Example JSON feed',
    url: 'https://jsonplaceholder.typicode.com/posts',
    silentAfterHours: 24,
  },
];

return sources.map((s) => ({ json: s }));

// Everything that matters happens here, and it is deliberately one node so
// the whole decision path can be read at once.
//
// Four things are checked, in this order:
//   1. did the request actually succeed          -> loud failure
//   2. did the payload parse and contain items   -> loud failure
//   3. is anything in it new                     -> quiet is fine here
//   4. has any source gone quiet for too long    -> loud failure
//
// Step 4 is the one most pipelines skip. Steps 1-3 catch a source that
// breaks. Step 4 catches a source that keeps answering 200 with nothing in
// it -- the failure nobody notices, because nothing ever looks wrong.
//
// NOTE ON THE SOURCE METADATA. The HTTP node runs with fullResponse, so its
// output is {body, headers, statusCode} and the id/label/silentAfterHours
// fields set upstream are NOT in it. They are pulled back from the Sources
// node by position. This is not a detail: the first draft of this workflow
// read them off the HTTP output, they were undefined, every source silently
// became id "unknown", and the silence check -- the whole point of the
// workflow -- could never fire. It looked like it worked. Nothing errored.

const sources = $('Sources').all().map((i) => i.json);

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};             // fingerprint -> timestamp
store.lastItemAt = store.lastItemAt || {}; // source id -> timestamp
store.lastRunAt = Date.now();

const now = Date.now();
const HOUR = 3600 * 1000;
const KEEP_SEEN_DAYS = 30;
const alerts = [];
const fresh = [];

function fingerprint(sourceId, item) {
  const basis = [item.id, item.url, item.title, item.guid]
    .filter(Boolean)
    .join('|') || JSON.stringify(item);
  let h = 5381;
  for (let i = 0; i < basis.length; i++) h = ((h * 33) ^ basis.charCodeAt(i)) >>> 0;
  return sourceId + ':' + h.toString(36);
}

const responses = $input.all();

responses.forEach((entry, idx) => {
  const source = sources[idx] || {};
  const id = source.id || ('position-' + idx);
  const label = source.label || id;

  // The Fetch node runs with neverError, so a failed request arrives here as
  // data instead of killing the run. That is the point: one dead source must
  // not stop the other sources from being checked.
  const status = entry.json.statusCode;
  const body = entry.json.body;

  if (typeof status === 'number' && (status < 200 || status >= 300)) {
    alerts.push({ kind: 'request_failed', source: id, label,
                  detail: 'HTTP ' + status });
    return;
  }

  let items = body;
  if (typeof items === 'string') {
    try {
      items = JSON.parse(items);
    } catch (e) {
      alerts.push({ kind: 'unparseable', source: id, label,
                    detail: 'body did not parse as JSON' });
      return;
    }
  }
  if (!Array.isArray(items)) items = items && items.items ? items.items : [];

  // An empty response is not an alert by itself. A source is allowed to have
  // nothing new. It only becomes an alert once it has been empty past its own
  // limit, which the silence check below decides.
  if (items.length === 0) return;

  store.lastItemAt[id] = now;

  for (const raw of items) {
    const item = (typeof raw === 'object' && raw !== null) ? raw : { value: raw };
    const fp = fingerprint(id, item);
    if (store.seen[fp]) continue;          // already delivered, do not repeat
    store.seen[fp] = now;
    fresh.push({ source: id, label, item });
  }
});

// --- silence check: the reason this workflow exists ---------------------
for (const source of sources) {
  if (!source.id) continue;
  const limit = (source.silentAfterHours || 24) * HOUR;
  const last = store.lastItemAt[source.id];
  if (last === undefined) {
    store.lastItemAt[source.id] = now;     // first ever run, start the clock
    continue;
  }
  if (now - last > limit) {
    alerts.push({
      kind: 'silent',
      source: source.id,
      label: source.label || source.id,
      detail: 'nothing new for ' + Math.round((now - last) / HOUR) + 'h '
            + '(limit ' + (source.silentAfterHours || 24) + 'h)',
    });
  }
}

// --- housekeeping so the store does not grow forever --------------------
const cutoff = now - KEEP_SEEN_DAYS * 24 * HOUR;
let dropped = 0;
for (const [fp, t] of Object.entries(store.seen)) {
  if (t < cutoff) { delete store.seen[fp]; dropped++; }
}

return [
  ...alerts.map((a) => ({ json: { type: 'alert', ...a } })),
  ...fresh.map((f) => ({ json: { type: 'item', ...f } })),
  { json: { type: 'run', sources: sources.length, freshCount: fresh.length,
            alertCount: alerts.length, prunedFingerprints: dropped } },
];

// Turn the three kinds of output into text a human will actually read,
// and drop the run summary so it never becomes a notification.
//
// Silence and failure are written differently from new items on purpose.
// A person who gets twenty notifications a day stops reading them; the two
// that mean 'this is broken' have to look different from the eighteen that
// mean 'here is a thing'.

const out = [];

for (const entry of $input.all()) {
  const d = entry.json;

  if (d.type === 'alert') {
    const head = d.kind === 'silent'
      ? 'SILENT — ' + d.label
      : 'BROKEN — ' + d.label;
    out.push({ json: {
      priority: 'high',
      text: head + '\n' + d.detail
          + '\n\nThis is the alert most pipelines never send.',
    } });
    continue;
  }

  if (d.type === 'item') {
    const it = d.item || {};
    const title = it.title || it.name || it.id || JSON.stringify(it).slice(0, 80);
    const link = it.url || it.link || '';
    out.push({ json: {
      priority: 'normal',
      text: '[' + d.label + '] ' + title + (link ? '\n' + link : ''),
    } });
  }
  // type === 'run' is intentionally dropped: useful in the execution log,
  // useless as a message.
}

return out;
